{"implementation": "def solve(case):
    payload = case.get('payload')
    if not isinstance(payload, dict):
        raise ValueError('Invalid case payload')
    segments = payload.get('segments')
    budget = payload.get('budget')
    if not isinstance(segments, list) or len(segments) == 0:
        raise ValueError('Missing or empty segments list')
    if not isinstance(budget, int):
        raise ValueError('Budget must be integer')

    sum_min = 0
    sum_max = 0
    for s in segments:
        if not isinstance(s, dict):
            raise ValueError('Segment must be dict')
        name = s.get('name')
        importance = s.get('importance')
        minimum = s.get('minimum')
        capacity = s.get('capacity')
        if not all(isinstance(x, int) for x in (importance, minimum, capacity)) or not isinstance(name, str):
            raise ValueError('Segment fields invalid')
        if minimum < 0 or capacity < minimum:
            raise ValueError('Minimum or capacity constraints violated')
        sum_min += minimum
        sum_max += capacity

    if budget < sum_min:
        raise ValueError('Budget below sum of minima')
    if budget > sum_max:
        raise ValueError('Budget exceeds total capacity')

    alloc = {s['name']: s['minimum'] for s in segments}
    remaining = budget - sum_min

    while remaining > 0:
        best_idx = None
        best_num = None
        best_den = None
        for i, s in enumerate(segments):
            name = s['name']
            if alloc[name] >= s['capacity']:
                continue
            cur_num = s['importance']
            cur_den = alloc[name] + 1
            if best_idx is None:
                best_idx = i
                best_num = cur_num
                best_den = cur_den
            else:
                # compare cur_num/best_den vs best_num/cur_den
                left = cur_num * best_den
                right = best_num * cur_den
                if left > right:
                    best_idx = i
                    best_num = cur_num
                    best_den = cur_den
                # tie: keep earlier index (i larger, so do nothing)
        if best_idx is None:
            raise ValueError('No segment available (should not happen)')
        best_name = segments[best_idx]['name']
        alloc[best_name] += 1
        remaining -= 1

    return {
        'allocations': alloc,
        'segment_order': [s['name'] for s in segments],
        'total_allocated': sum(alloc.values())
    }"}
